// Exercise database.
// pattern: squat | hinge | lunge | pushH | pushV | pull | core | carry | cardio
// tier: 1 (easiest) -> 3 (hardest) — used for progressive difficulty scaling
// equipment: bodyweight | dumbbell | bench | plate | curlbar | table | treadmill
// timeBased: true -> duration (sec) instead of reps

const EXERCISES = [
  // ---------- SQUAT ----------
  { id:'bw_squat', name:'Bodyweight Squat', pattern:'squat', focus:['legs','glutes'], equipment:['bodyweight'], tier:1, reps:'12-15', cue:'Feet shoulder-width, sit back like sitting in a chair, chest up.' , images:['img/ex/bw_squat/0.jpg','img/ex/bw_squat/1.jpg'], steps:['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.','Begin the movement by flexing your knees and hips, sitting back with your hips.','Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.'] },
  { id:'goblet_squat', name:'Goblet Squat', pattern:'squat', focus:['legs','glutes'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Hold one dumbbell vertically at your chest, squat down, drive through heels.' , images:['img/ex/goblet_squat/0.jpg','img/ex/goblet_squat/1.jpg'], steps:['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.','Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.','At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.'] },
  { id:'sumo_squat', name:'Sumo Squat', pattern:'squat', focus:['legs','glutes'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Wide stance, toes out, dumbbell hanging between legs, squat straight down.' , images:['img/ex/sumo_squat/0.jpg','img/ex/sumo_squat/1.jpg'], steps:['Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.','Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.','Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.','Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.'] },
  { id:'pulse_squat', name:'Pulse Squat', pattern:'squat', focus:['legs','glutes'], equipment:['bodyweight'], tier:3, reps:'15-20', cue:'Lower to a squat and pulse 2 inches up and down before standing.' , images:['img/ex/pulse_squat/0.jpg','img/ex/pulse_squat/1.jpg'], steps:['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.','Begin the movement by flexing your knees and hips, sitting back with your hips.','Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.'] },
  { id:'squat_press', name:'Squat to Shoulder Press', pattern:'squat', focus:['legs','shoulders'], equipment:['dumbbell'], tier:3, reps:'10-12', cue:'Squat down holding dumbbells at shoulders, as you stand press them overhead.' , images:['img/ex/squat_press/0.jpg','img/ex/squat_press/1.jpg'], steps:['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.','Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.','At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.','As you begin the next repetition, return the weights to the shoulders.'] },
  { id:'wall_sit', name:'Wall Sit', pattern:'squat', focus:['legs'], equipment:['bodyweight'], tier:2, timeBased:true, duration:30, cue:'Back flat against a wall, thighs parallel to floor, hold.', steps:['Stand with your back flat against a wall, feet shoulder-width apart.','Slide down until your knees are bent to about a right angle, like sitting in an invisible chair.','Keep your back pressed to the wall and your knees above your ankles. Hold and breathe steadily.'] },

  // ---------- HINGE ----------
  { id:'glute_bridge', name:'Glute Bridge', pattern:'hinge', focus:['glutes','core'], equipment:['bodyweight'], tier:1, reps:'12-15', cue:'Lie on back, knees bent, drive hips up squeezing glutes at the top.' , images:['img/ex/glute_bridge/0.jpg','img/ex/glute_bridge/1.jpg'], steps:['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.','Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.','Slowly go back to the starting position as you breathe in.'] },
  { id:'db_rdl', name:'Dumbbell Romanian Deadlift', pattern:'hinge', focus:['legs','glutes'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Soft knees, hinge at hips lowering dumbbells along shins, feel the hamstring stretch.' , images:['img/ex/db_rdl/0.jpg','img/ex/db_rdl/1.jpg'], steps:['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.','Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.','Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.','Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.'] },
  { id:'single_leg_glute_bridge', name:'Single-Leg Glute Bridge', pattern:'hinge', focus:['glutes','core'], equipment:['bodyweight'], tier:2, reps:'10 per side', cue:'One foot planted, other leg extended, drive hips up through the planted heel.' , images:['img/ex/single_leg_glute_bridge/0.jpg','img/ex/single_leg_glute_bridge/1.jpg'], steps:['Lay on the floor with your feet flat and knees bent.','Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.','Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.','Extend as far as possible, pause and then return to the starting position.'] },
  { id:'weighted_bridge', name:'Weighted Glute Bridge', pattern:'hinge', focus:['glutes'], equipment:['dumbbell'], tier:3, reps:'12-15', cue:'Rest a dumbbell on your hips, bridge up and squeeze at the top.' , images:['img/ex/weighted_bridge/0.jpg','img/ex/weighted_bridge/1.jpg'], steps:['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.','Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.','Extend as far as possible, then reverse the motion to return to the starting position.'] },
  { id:'good_morning', name:'Dumbbell Good Morning', pattern:'hinge', focus:['legs','glutes'], equipment:['dumbbell'], tier:3, reps:'10-12', cue:'Dumbbell across upper back, hinge forward keeping back flat, return to standing.' , images:['img/ex/good_morning/0.jpg','img/ex/good_morning/1.jpg'], steps:['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.','Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.','Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.'] },

  // ---------- LUNGE ----------
  { id:'bw_lunge', name:'Bodyweight Lunge', pattern:'lunge', focus:['legs','glutes'], equipment:['bodyweight'], tier:1, reps:'10 per side', cue:'Step forward, drop back knee toward floor, push back to start.' , images:['img/ex/bw_lunge/0.jpg','img/ex/bw_lunge/1.jpg'], steps:['Begin standing with your feet shoulder width apart and your hands on your hips.','Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.','Drive through the heel of your lead foot and extend both knees to raise yourself back up.','Step forward with your rear foot, repeating the lunge on the opposite leg.'] },
  { id:'db_reverse_lunge', name:'Dumbbell Reverse Lunge', pattern:'lunge', focus:['legs','glutes'], equipment:['dumbbell'], tier:2, reps:'10 per side', cue:'Step backward into a lunge holding dumbbells at your sides.' , images:['img/ex/db_reverse_lunge/0.jpg','img/ex/db_reverse_lunge/1.jpg'], steps:['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.','Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.','Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.','Now repeat with the opposite leg.'] },
  { id:'step_up', name:'Step-Up (bench)', pattern:'lunge', focus:['legs','glutes'], equipment:['bench'], tier:2, reps:'10 per side', cue:'Step fully onto the bench, drive through the lead foot, step down with control.' , images:['img/ex/step_up/0.jpg','img/ex/step_up/1.jpg'], steps:['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.'] },
  { id:'db_step_up', name:'Weighted Step-Up (bench)', pattern:'lunge', focus:['legs','glutes'], equipment:['bench','dumbbell'], tier:3, reps:'10 per side', cue:'Same as step-up, holding a dumbbell in each hand.' , images:['img/ex/db_step_up/0.jpg','img/ex/db_step_up/1.jpg'], steps:['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.'] },
  { id:'curtsy_lunge', name:'Curtsy Lunge', pattern:'lunge', focus:['legs','glutes'], equipment:['bodyweight'], tier:2, reps:'10 per side', cue:'Step one leg behind and across, lower into a curtsy, return to standing.', steps:['Stand tall, feet hip-width apart, hands on your hips or clasped at your chest.','Step one leg behind and across the other, bending both knees until your back knee hovers just above the floor.','Push through your front heel to return to standing, then repeat on the other side.'] },
  { id:'lateral_lunge', name:'Lateral Lunge', pattern:'lunge', focus:['legs','glutes'], equipment:['bodyweight'], tier:2, reps:'10 per side', cue:'Step wide to one side, sit back into that hip, other leg stays straight.', steps:['Stand with feet together, hands clasped at your chest.','Step out wide to one side and sit your hips back and down over that leg, keeping the other leg straight.','Push off the bent leg to return to center, then repeat on the other side.'] },
  { id:'bulgarian_split_squat', name:'Bulgarian Split Squat (bench)', pattern:'lunge', focus:['legs','glutes'], equipment:['bench'], tier:3, reps:'8-10 per side', cue:'Rear foot up on the bench, lower straight down on the front leg.', steps:['Stand a couple of feet in front of a bench and rest the top of one foot on it, behind you.','Lower straight down by bending your front knee until your back knee nearly touches the floor.','Drive through your front heel to stand back up. Finish all reps, then switch legs.'] },

  // ---------- PUSH (horizontal) ----------
  { id:'knee_pushup', name:'Knee Push-Up', pattern:'pushH', focus:['chest','arms'], equipment:['bodyweight'], tier:1, reps:'8-12', cue:'Knees down, hands under shoulders, lower chest to floor, press up.' , images:['img/ex/knee_pushup/0.jpg','img/ex/knee_pushup/1.jpg'], steps:['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.','Next, lower yourself downward until your chest almost touches the floor as you inhale.','Now breathe out and press your upper body back up to the starting position while squeezing your chest.','After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.'] },
  { id:'pushup', name:'Push-Up', pattern:'pushH', focus:['chest','arms'], equipment:['bodyweight'], tier:2, reps:'8-12', cue:'Straight line head to heels, lower chest to floor, press up.' , images:['img/ex/pushup/0.jpg','img/ex/pushup/1.jpg'], steps:['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.','Next, lower yourself downward until your chest almost touches the floor as you inhale.','Now breathe out and press your upper body back up to the starting position while squeezing your chest.','After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.'] },
  { id:'incline_pushup', name:'Incline Push-Up (coffee table)', pattern:'pushH', focus:['chest','arms'], equipment:['table'], tier:1, reps:'10-12', cue:'Hands on the coffee table, body straight, lower and press up — easier angle.' , images:['img/ex/incline_pushup/0.jpg','img/ex/incline_pushup/1.jpg'], steps:['Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.','Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.','Push body up until arms are extended. Repeat.'] },
  { id:'decline_pushup', name:'Decline Push-Up (bench)', pattern:'pushH', focus:['chest','shoulders'], equipment:['bench'], tier:3, reps:'8-10', cue:'Feet up on the bench, hands on floor, lower chest toward the ground.' , images:['img/ex/decline_pushup/0.jpg','img/ex/decline_pushup/1.jpg'], steps:['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.','Next, lower yourself downward until your chest almost touches the floor as you inhale.','Now breathe out and press your upper body back up to the starting position while squeezing your chest.','After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.'] },
  { id:'db_chest_press', name:'Dumbbell Floor Chest Press', pattern:'pushH', focus:['chest','arms'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Lie on floor, press dumbbells straight up over your chest.' , images:['img/ex/db_chest_press/0.jpg','img/ex/db_chest_press/1.jpg'], steps:['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.','Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.','Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.'] },
  { id:'db_bench_press', name:'Dumbbell Bench Press', pattern:'pushH', focus:['chest','arms'], equipment:['dumbbell','bench'], tier:3, reps:'10-12', cue:'Lie on the bench, press dumbbells up over your chest, lower with control.' , images:['img/ex/db_bench_press/0.jpg','img/ex/db_bench_press/1.jpg'], steps:['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.','Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.','Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.','Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.'] },
  { id:'db_fly', name:'Dumbbell Floor Fly', pattern:'pushH', focus:['chest'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Arms slightly bent, open wide then bring dumbbells together over chest.' , images:['img/ex/db_fly/0.jpg','img/ex/db_fly/1.jpg'], steps:['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.','Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you\'re pressing them, but stop and hold just before you lock out. This will be your starting position.','With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.','Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.'] },

  // ---------- PUSH (vertical) ----------
  { id:'pike_pushup', name:'Pike Push-Up', pattern:'pushV', focus:['shoulders','arms'], equipment:['bodyweight'], tier:3, reps:'8-10', cue:'Hips high in a pike, lower the top of your head toward the floor.', steps:['Start in a downward-dog position: hips lifted high, hands and feet on the floor forming an inverted V.','Bend your elbows to lower the top of your head toward the floor, keeping your hips high.','Press back up through your hands to the starting position.'] },
  { id:'db_shoulder_press', name:'Dumbbell Shoulder Press', pattern:'pushV', focus:['shoulders'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Press dumbbells from shoulder height straight overhead.' , images:['img/ex/db_shoulder_press/0.jpg','img/ex/db_shoulder_press/1.jpg'], steps:['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.','Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.','Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.','Now, exhale and push the dumbbells upward until they touch at the top.'] },
  { id:'db_lateral_raise', name:'Dumbbell Lateral Raise', pattern:'pushV', focus:['shoulders'], equipment:['dumbbell'], tier:2, reps:'12-15', cue:'Light weight, raise arms out to the sides to shoulder height.' , images:['img/ex/db_lateral_raise/0.jpg','img/ex/db_lateral_raise/1.jpg'], steps:['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.','While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.','Lower the dumbbells back down slowly to the starting position as you inhale.','Repeat for the recommended amount of repetitions.'] },
  { id:'db_front_raise', name:'Dumbbell Front Raise', pattern:'pushV', focus:['shoulders'], equipment:['dumbbell'], tier:2, reps:'12-15', cue:'Raise dumbbells straight in front to shoulder height, control the descent.' , images:['img/ex/db_front_raise/0.jpg','img/ex/db_front_raise/1.jpg'], steps:['Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.','While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.','Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.','Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.'] },
  { id:'arnold_press', name:'Arnold Press', pattern:'pushV', focus:['shoulders'], equipment:['dumbbell'], tier:3, reps:'10-12', cue:'Start palms facing you, rotate and press overhead, reverse on the way down.' , images:['img/ex/arnold_press/0.jpg','img/ex/arnold_press/1.jpg'], steps:['Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.','Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.','Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.','After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.'] },

  // ---------- PULL ----------
  { id:'db_bent_row', name:'Dumbbell Bent-Over Row', pattern:'pull', focus:['back','arms'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Hinge forward, flat back, row dumbbells to your ribs, squeeze shoulder blades.' , images:['img/ex/db_bent_row/0.jpg','img/ex/db_bent_row/1.jpg'], steps:['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.','Slowly lower the weight again to the starting position as you inhale.','Repeat for the recommended amount of repetitions.'] },
  { id:'db_single_row', name:'Single-Arm Row (bench)', pattern:'pull', focus:['back','arms'], equipment:['dumbbell','bench'], tier:2, reps:'10 per side', cue:'One knee and hand on the bench, row the dumbbell to your hip.' , images:['img/ex/db_single_row/0.jpg','img/ex/db_single_row/1.jpg'], steps:['Choose a flat bench and place a dumbbell on each side of it.','Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.','Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.','Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.'] },
  { id:'reverse_fly', name:'Dumbbell Reverse Fly', pattern:'pull', focus:['back','shoulders'], equipment:['dumbbell'], tier:2, reps:'12-15', cue:'Hinge forward, raise dumbbells out to the sides, squeeze shoulder blades together.' , images:['img/ex/reverse_fly/0.jpg','img/ex/reverse_fly/1.jpg'], steps:['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).','Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.','Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.','The arms should be elevated until they are parallel to the floor.'] },
  { id:'superman', name:'Superman Hold', pattern:'pull', focus:['back','core'], equipment:['bodyweight'], tier:1, timeBased:true, duration:25, cue:'Lie face down, lift arms, chest and legs off the floor together, hold.' , images:['img/ex/superman/0.jpg','img/ex/superman/1.jpg'], steps:['To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.','Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.','Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.','Repeat for the recommended amount of repetitions prescribed in your program.'] },
  { id:'bar_hang', name:'Dead Hang (pull-up bar)', pattern:'pull', focus:['back','arms'], equipment:['bodyweight'], tier:2, timeBased:true, duration:20, cue:'Hang from the bar with arms straight, shoulders engaged — builds grip and back without needing a pull-up.', steps:['Reach up and grip the pull-up bar with both hands, slightly wider than shoulder-width.','Let your feet leave the floor so your full body weight hangs from your arms, shoulders relaxed but engaged.','Keep breathing steadily and hold for the full time — great for grip and back strength, no pull-up needed.'] },
  { id:'curlbar_row', name:'Curl Bar Bent-Over Row', pattern:'pull', focus:['back','arms'], equipment:['curlbar'], tier:3, reps:'10-12', cue:'Hinge forward, flat back, row the bar to your waist.' , images:['img/ex/curlbar_row/0.jpg','img/ex/curlbar_row/1.jpg'], steps:['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.','Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.','Then inhale and slowly lower the barbell back to the starting position.','Repeat for the recommended amount of repetitions.'] },

  // ---------- ARMS (biceps/triceps direct) ----------
  { id:'curlbar_curl', name:'Curl Bar Bicep Curl', pattern:'pull', focus:['arms'], equipment:['curlbar'], tier:2, reps:'10-12', cue:'Elbows pinned to your sides, curl the bar up, squeeze, lower slowly.' , images:['img/ex/curlbar_curl/0.jpg','img/ex/curlbar_curl/1.jpg'], steps:['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.'] },
  { id:'db_hammer_curl', name:'Dumbbell Hammer Curl', pattern:'pull', focus:['arms'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Palms facing each other, curl straight up without rotating the wrist.' , images:['img/ex/db_hammer_curl/0.jpg','img/ex/db_hammer_curl/1.jpg'], steps:['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.','After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.'] },
  { id:'bench_dip', name:'Bench Tricep Dip', pattern:'pushH', focus:['arms'], equipment:['bench'], tier:2, reps:'10-12', cue:'Hands on bench behind you, lower hips straight down, press back up.' , images:['img/ex/bench_dip/0.jpg','img/ex/bench_dip/1.jpg'], steps:['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.','Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.','Using your triceps to bring your torso up again, lift yourself back to the starting position.','Repeat for the recommended amount of repetitions.'] },
  { id:'db_overhead_tricep', name:'Dumbbell Overhead Tricep Extension', pattern:'pushV', focus:['arms'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'One dumbbell held with both hands overhead, lower behind your head, extend back up.' , images:['img/ex/db_overhead_tricep/0.jpg','img/ex/db_overhead_tricep/1.jpg'], steps:['To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.','The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.','Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.','Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.'] },
  { id:'db_kickback', name:'Dumbbell Tricep Kickback', pattern:'pushH', focus:['arms'], equipment:['dumbbell'], tier:2, reps:'10-12', cue:'Hinge forward, elbow pinned high, extend the forearm straight back.' , images:['img/ex/db_kickback/0.jpg','img/ex/db_kickback/1.jpg'], steps:['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.','Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.','After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.','Repeat the movement for the prescribed amount of repetitions.'] },

  // ---------- CORE ----------
  { id:'plank', name:'Forearm Plank', pattern:'core', focus:['core'], equipment:['bodyweight'], tier:1, timeBased:true, duration:30, cue:'Forearms down, straight line head to heels, brace your abs.' , images:['img/ex/plank/0.jpg','img/ex/plank/1.jpg'], steps:['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.','Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.'] },
  { id:'side_plank', name:'Side Plank', pattern:'core', focus:['core'], equipment:['bodyweight'], tier:2, timeBased:true, duration:20, cue:'Stack feet, prop up on one forearm, lift hips into a straight line. Both sides.' , images:['img/ex/side_plank/0.jpg','img/ex/side_plank/1.jpg'], steps:['Lie on your side with your legs stacked and propped up on one forearm, elbow under your shoulder.','Lift your hips off the floor until your body forms a straight line from head to feet.','Hold, keeping your hips lifted and core braced, then switch sides for the next set.'] },
  { id:'bicycle_crunch', name:'Bicycle Crunch', pattern:'core', focus:['core'], equipment:['bodyweight'], tier:2, reps:'20 total', cue:'Opposite elbow to opposite knee, slow and controlled, exhale on each twist.', steps:['Lie on your back, hands lightly behind your head, knees bent and lifted over your hips.','Bring one elbow toward the opposite knee while extending the other leg out, twisting through your torso.','Switch sides in a slow, controlled pedaling motion — quality over speed.'] },
  { id:'dead_bug', name:'Dead Bug', pattern:'core', focus:['core'], equipment:['bodyweight'], tier:1, reps:'10 per side', cue:'Lower back pressed flat, extend opposite arm and leg, return, switch sides.' , images:['img/ex/dead_bug/0.jpg','img/ex/dead_bug/1.jpg'], steps:['Begin lying on your back with your hands extended above you toward the ceiling.','Bring your feet, knees, and hips up to 90 degrees.','Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.','Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.'] },
  { id:'plate_russian_twist', name:'Weighted Russian Twist', pattern:'core', focus:['core'], equipment:['plate'], tier:2, reps:'16 total', cue:'Lean back slightly, feet off floor if possible, twist the plate side to side.' , images:['img/ex/plate_russian_twist/0.jpg','img/ex/plate_russian_twist/1.jpg'], steps:['Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.','Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.','Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.','Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.'] },
  { id:'mountain_climber', name:'Mountain Climbers', pattern:'core', focus:['core','cardio'], equipment:['bodyweight'], tier:2, timeBased:true, duration:30, cue:'Plank position, drive knees to chest quickly, keep hips level.' , images:['img/ex/mountain_climber/0.jpg','img/ex/mountain_climber/1.jpg'], steps:['Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.','Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.'] },
  { id:'leg_raise', name:'Lying Leg Raise', pattern:'core', focus:['core'], equipment:['bodyweight'], tier:2, reps:'12-15', cue:'Lower back pressed down, raise straight legs to vertical, lower slowly without touching the floor.' , images:['img/ex/leg_raise/0.jpg','img/ex/leg_raise/1.jpg'], steps:['Lie with your back flat on a bench and your legs extended in front of you off the end.','Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.','As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.','Now, as you inhale, slowly lower your legs back down to the starting position.'] },
  { id:'plank_shoulder_tap', name:'Plank Shoulder Taps', pattern:'core', focus:['core'], equipment:['bodyweight'], tier:2, reps:'16 total', cue:'High plank, tap opposite shoulder with each hand, keep hips still.', steps:['Start in a high plank: hands under shoulders, body in a straight line, feet a little wider than hip-width for stability.','Without rocking your hips, lift one hand to tap the opposite shoulder.','Replace it and repeat with the other hand, alternating while keeping your core braced.'] },
  { id:'hollow_hold', name:'Hollow Body Hold', pattern:'core', focus:['core'], equipment:['bodyweight'], tier:3, timeBased:true, duration:20, cue:'Lower back pressed to floor, arms and legs extended and lifted, hold the dish shape.', steps:['Lie on your back and press your lower back flat into the floor.','Lift your shoulders and legs a few inches off the ground, reaching your arms overhead — a shallow \'dish\' shape.','Hold the position, keeping your lower back glued to the floor and breathing steadily.'] },

  // ---------- CARDIO / FULL BODY / CARRY ----------
  { id:'jumping_jacks', name:'Jumping Jacks', pattern:'cardio', focus:['cardio'], equipment:['bodyweight'], tier:1, timeBased:true, duration:30, cue:'Classic jacks — keep a light, quick rhythm.', steps:['Stand tall with feet together and arms at your sides.','Jump your feet out wide while raising your arms overhead.','Jump back to the start and repeat at a light, steady rhythm.'] },
  { id:'high_knees', name:'High Knees', pattern:'cardio', focus:['cardio','legs'], equipment:['bodyweight'], tier:2, timeBased:true, duration:30, cue:'Drive knees up to hip height quickly, pump your arms.', steps:['Stand tall with feet hip-width apart.','Drive one knee up toward hip height, then quickly switch legs, pumping your arms like a light jog in place.','Stay light on your feet and keep your chest up throughout.'] },
  { id:'squat_jump', name:'Squat Jump', pattern:'cardio', focus:['legs','cardio'], equipment:['bodyweight'], tier:3, reps:'10-12', cue:'Squat down then explode straight up, land soft.' , images:['img/ex/squat_jump/0.jpg','img/ex/squat_jump/1.jpg'], steps:['Cross your arms over your chest.','With your head up and your back straight, position your feet at shoulder width.','Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.','Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.'] },
  { id:'burpee_no_pushup', name:'Burpee (no push-up)', pattern:'cardio', focus:['cardio','legs'], equipment:['bodyweight'], tier:3, reps:'8-10', cue:'Squat, kick feet back to plank, jump feet in, stand and jump up.', steps:['Start standing, then squat down and place your hands on the floor in front of you.','Kick your feet back into a plank position, then immediately hop them back in toward your hands.','Stand up and finish with a small jump, arms overhead. Reset and repeat.'] },
  { id:'treadmill_interval', name:'Treadmill Interval', pattern:'cardio', focus:['cardio'], equipment:['treadmill'], tier:2, timeBased:true, duration:60, cue:'Alternate 30s brisk walk/jog with 30s faster pace, repeat.' , images:['img/ex/treadmill_interval/0.jpg','img/ex/treadmill_interval/1.jpg'], steps:['Step onto the treadmill and set it to manual, or pick an interval program.','Walk or jog at a brisk, comfortable pace for 30 seconds.','Push the pace faster — a light jog or fast walk — for 30 seconds, then ease back and repeat.','Hold the handrails only to check your heart rate or steady yourself, not throughout the move.'] },
  { id:'treadmill_incline_walk', name:'Treadmill Incline Walk', pattern:'cardio', focus:['cardio','legs'], equipment:['treadmill'], tier:1, timeBased:true, duration:90, cue:'Raise the incline, walk at a pace you can hold while talking in short sentences.' , images:['img/ex/treadmill_incline_walk/0.jpg','img/ex/treadmill_incline_walk/1.jpg'], steps:['Step onto the treadmill and raise the incline a few percent.','Walk at a pace you could hold a conversation at — brisk, not rushed.','Keep your posture tall; only use the handrails to steady yourself, not to lean on.'] },
  { id:'db_farmer_carry', name:"Farmer's Carry", pattern:'carry', focus:['core','arms'], equipment:['dumbbell'], tier:2, timeBased:true, duration:30, cue:'A dumbbell in each hand, walk tall with shoulders back for the full time.' , images:['img/ex/db_farmer_carry/0.jpg','img/ex/db_farmer_carry/1.jpg'], steps:['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren\'t available. Begin by standing between the implements.','After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.','Walk taking short, quick steps, and don\'t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.'] },
  { id:'plate_overhead_carry', name:'Overhead Plate Carry', pattern:'carry', focus:['core','shoulders'], equipment:['plate'], tier:3, timeBased:true, duration:20, cue:'Press the plate overhead and walk slowly, keep your core braced.', steps:['Press a weight plate overhead with both hands, arms fully extended and braced.','Keeping your core tight and the plate steady overhead, walk slowly and deliberately for the set time.','If your shoulders fatigue, lower the plate, reset your brace, and continue.'] },
  { id:'table_tricep_dip', name:'Coffee Table Tricep Dip', pattern:'pushH', focus:['arms'], equipment:['table'], tier:1, reps:'10-12', cue:'Hands on the table edge behind you, lower hips straight down and press up.' , images:['img/ex/table_tricep_dip/0.jpg','img/ex/table_tricep_dip/1.jpg'], steps:['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.','Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.','Using your triceps to bring your torso up again, lift yourself back to the starting position.','Repeat for the recommended amount of repetitions.'] },
  { id:'step_up_cardio', name:'Fast Step-Ups (coffee table)', pattern:'cardio', focus:['legs','cardio'], equipment:['table'], tier:2, timeBased:true, duration:30, cue:'Step up and down on the coffee table at a quick, steady pace.' , images:['img/ex/step_up_cardio/0.jpg','img/ex/step_up_cardio/1.jpg'], steps:['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).','Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.','Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.','Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.'] },
];

// Warm-up and cool-down pools (always bodyweight, low intensity, time-based)
const WARMUPS = [
  { id:'w_march', name:'March in Place', duration:30, cue:'Easy marching, swing your arms, get your heart rate up gently.', steps:['Stand tall and march in place, lifting your knees to about hip height.','Swing your arms naturally with each step to get your whole body moving.','Keep a steady, comfortable pace to ease your heart rate up.'] },
  { id:'w_arm_circle', name:'Arm Circles', duration:20, cue:'Small to big circles forward, then backward.', images:['img/ex/w_arm_circle/0.jpg','img/ex/w_arm_circle/1.jpg'], steps:['Stand tall and stretch your arms straight out to the sides, parallel to the floor.','Make small circles — about a foot wide — with both arms for 10 seconds.','Reverse direction and circle the other way for 10 seconds.'] },
  { id:'w_bodyweight_squat', name:'Bodyweight Squats', duration:30, cue:'Slow, controlled squats to open up the hips and knees.', images:['img/ex/bw_squat/0.jpg','img/ex/bw_squat/1.jpg'], steps:['Stand with feet shoulder-width apart, hands out in front or behind your head.','Sit your hips back and down like sitting into a chair, keeping your chest up.','Rise back to standing. Keep the pace slow and controlled to open up your hips and knees.'] },
  { id:'w_cat_cow', name:'Cat-Cow', duration:30, cue:'On hands and knees, alternate arching and rounding your spine.', images:['img/ex/w_cat_cow/0.jpg','img/ex/w_cat_cow/1.jpg'], steps:['Start on hands and knees, hands under your shoulders, knees under your hips.','Round your spine up toward the ceiling and tuck your chin — the \'cat\'. Hold briefly.','Then drop your belly, lift your chest and tailbone, and look slightly up — the \'cow\'.','Keep alternating smoothly, matching the movement to your breath.'] },
  { id:'w_leg_swing', name:'Leg Swings', duration:20, cue:'Hold something steady, swing each leg forward and back, then side to side.', steps:['Hold onto something stable — a wall or the back of a chair — for balance.','Swing one leg forward and back in a controlled motion, keeping your torso upright.','After 8-10 swings, turn side-on and swing the same leg side to side, then switch legs.'] },
  { id:'w_jacks_slow', name:'Slow Jumping Jacks', duration:30, cue:'Half-pace jacks to ease into it.', steps:['Stand tall with feet together and arms at your sides.','Step or hop your feet out wide while raising your arms overhead.','Return to the start at a relaxed, half-speed pace to ease into the workout.'] },
];
const COOLDOWNS = [
  { id:'c_quad_stretch', name:'Quad Stretch', duration:25, cue:'Stand tall, pull one heel to your glute, hold, switch sides.', images:['img/ex/c_quad_stretch/0.jpg','img/ex/c_quad_stretch/1.jpg'], steps:['Stand tall, holding onto something steady if needed.','Bend one knee and grab that foot behind you, gently pulling your heel toward your glutes.','Keep your knees close together and hold, feeling the stretch down the front of your thigh. Switch sides.'] },
  { id:'c_hamstring_stretch', name:'Hamstring Stretch', duration:25, cue:'Hinge forward with a soft bend in the knees, reach toward your toes.', images:['img/ex/c_hamstring_stretch/0.jpg','img/ex/c_hamstring_stretch/1.jpg'], steps:['Lie on your back and extend one leg straight up toward the ceiling.','Lace your hands behind your thigh or calf and gently pull it toward you, keeping the other leg flat on the floor.','Hold the stretch, then switch legs.'] },
  { id:'c_chest_stretch', name:'Chest Opener', duration:20, cue:'Clasp hands behind your back, lift your chest, pull shoulders back.', images:['img/ex/c_chest_stretch/0.jpg','img/ex/c_chest_stretch/1.jpg'], steps:['Stand tall with your arms straight out in front of you, palms together.','Slowly swing your arms back and apart as far as comfortable, feeling a stretch across your chest.','Bring them back together and repeat, nice and slow, 8-10 times.'] },
  { id:'c_child_pose', name:"Child's Pose", duration:30, cue:'Sit back onto your heels, arms stretched forward, relax your back.', images:['img/ex/c_child_pose/0.jpg','img/ex/c_child_pose/1.jpg'], steps:['Kneel on the floor and sit your hips back toward your heels.','Walk your hands forward and lower your chest toward the floor, arms stretched out ahead of you.','Relax your shoulders and breathe into your back. Rest your forehead down if comfortable.'] },
  { id:'c_calf_stretch', name:'Calf Stretch', duration:20, cue:'Step one foot back, press the heel down, lean into the wall gently.', images:['img/ex/c_calf_stretch/0.jpg','img/ex/c_calf_stretch/1.jpg'], steps:['Stand facing a wall, a few feet back, and stagger your stance with one foot forward.','Lean forward and rest your hands on the wall, keeping your back heel, hip and head in a straight line.','Press your back heel down toward the floor. Hold, then switch sides.'] },
  { id:'c_deep_breath', name:'Deep Breathing', duration:30, cue:'Slow breaths in through the nose, out through the mouth, let your heart rate settle.', steps:['Sit or stand comfortably and relax your shoulders.','Breathe in slowly through your nose for a count of four, filling your belly.','Breathe out through your mouth for a count of six. Repeat, letting your heart rate settle.'] },
];

if (typeof module !== 'undefined') module.exports = { EXERCISES, WARMUPS, COOLDOWNS };
